import React from "react";
import {
  Routes,
  Route
} from "react-router-dom";

import Sidebar from "./components/Sidebar";

import Dashboard from "./pages/Dashboard";
import Threats from "./pages/Threats";
import Incidents from "./pages/Incidents";
import Packets from "./pages/Packets";
import Settings from "./pages/Settings";

function App() {
  return (
    <div style={styles.app}>
      <Sidebar />

      <div style={styles.content}>
        <Routes>
          <Route
            path="/"
            element={<Dashboard />}
          />

          <Route
            path="/threats"
            element={<Threats />}
          />

          <Route
            path="/incidents"
            element={<Incidents />}
          />

          <Route
            path="/packets"
            element={<Packets />}
          />

          <Route
            path="/settings"
            element={<Settings />}
          />
        </Routes>
      </div>
    </div>
  );
}

const styles = {
  app: {
    display: "flex",
    background: "#0f172a",
    color: "white",
    minHeight: "100vh"
  },

  content: {
    flex: 1,
    padding: "20px"
  }
};

export default App;
